<script setup lang="ts">
const db=useSupabaseClient(),route=useRoute()
const token=computed(()=>typeof route.query.token==='string'?route.query.token:'')
const email=ref(''),password=ref(''),given=ref(''),family=ref(''),busy=ref(false),error=ref(''),message=ref(''),signedIn=ref(false),school=ref('')
const redirect=computed(()=>`${windowOrigin()}/staff/register${token.value?'?token='+encodeURIComponent(token.value):''}`)
function windowOrigin(){return import.meta.client?window.location.origin:''}
onMounted(async()=>{const {data:{user}}=await db.auth.getUser();signedIn.value=!!user;if(user){email.value=user.email||'';await lookup()}})
async function lookup(){if(!email.value)return;const {data}=await db.rpc('staff_signup_school',{p_email:email.value});school.value=data?.[0]?.school_name||''}
async function signUp(){error.value='';message.value='';if(!/^[a-f0-9]{64}$/i.test(token.value)){error.value='A valid staff invitation link is required.';return}busy.value=true;try{const {error:e}=await db.auth.signUp({email:email.value.trim(),password:password.value,options:{data:{full_name:`${given.value.trim()} ${family.value.trim()}`},emailRedirectTo:redirect.value}});if(e)throw e;message.value='Check your email for verification, then return to this page and sign in. Your invitation link is preserved.'}catch(e:any){error.value=e.message||'Unable to register'}finally{busy.value=false}}
async function signIn(){error.value='';busy.value=true;try{const {error:e}=await db.auth.signInWithPassword({email:email.value.trim(),password:password.value});if(e)throw e;signedIn.value=true;await lookup()}catch(e:any){error.value=e.message||'Sign in failed'}finally{busy.value=false}}
async function submit(){error.value='';message.value='';if(!/^[a-f0-9]{64}$/i.test(token.value)){error.value='A valid staff invitation link is required.';return}busy.value=true;try{const {data,error:e}=await db.rpc('submit_staff_request',{p_given_name:given.value.trim(),p_family_name:family.value.trim(),p_token:token.value||null});if(e)throw e;message.value=data==='already_member'?'You already have school access. Open your dashboard.':'Your staff registration is pending School Administrator approval.'}catch(e:any){error.value=e.message||'Unable to submit request'}finally{busy.value=false}}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/">← Home</NuxtLink><div class="card" style="max-width:620px;margin:2rem auto"><h1>School Staff Registration</h1><p>Register with your school email. Your School Administrator must approve your access.</p><p v-if="token" class="notice">Invitation link detected. Register or sign in with the email address that received it.</p><p v-if="!/^[a-f0-9]{64}$/i.test(token)" class="error" role="alert">Staff registration requires an invitation link issued by your school administrator.</p><form v-if="!signedIn && /^[a-f0-9]{64}$/i.test(token)" @submit.prevent="signUp"><label class="field"><span>School email</span><input v-model="email" type="email" required autocomplete="email" @blur="lookup"></label><p v-if="school" class="success">School: {{school}}</p><label class="field"><span>Password (minimum 8 characters)</span><input v-model="password" type="password" minlength="8" required></label><label class="field"><span>First name</span><input v-model="given" required maxlength="100"></label><label class="field"><span>Last name</span><input v-model="family" required maxlength="100"></label><button class="btn" :disabled="busy">Create staff account</button><button type="button" class="btn" style="margin-left:.75rem" :disabled="busy" @click="signIn">Already registered? Sign in</button></form><form v-else-if="signedIn && /^[a-f0-9]{64}$/i.test(token)" @submit.prevent="submit"><p>Signed in as <strong>{{email}}</strong></p><label class="field"><span>First name</span><input v-model="given" required maxlength="100"></label><label class="field"><span>Last name</span><input v-model="family" required maxlength="100"></label><button class="btn" :disabled="busy">Submit staff registration</button><NuxtLink style="margin-left:1rem" to="/school/dashboard">School dashboard</NuxtLink></form><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p></div></div></div></template>
